GUIDE={
 'thesis':'吉林省情用地图、层级树、时间线、产业因果链和年度数据卡串起来。先判断问题属于位置、角色、时间、机制还是数据口径，再回答。',
 'reasoning':['区划题先定层级：长春是省会，吉林市是与省同名的地级市，延边是自治州，延吉是州首府。名字相近和民族称谓都不能代替行政归属。','地理题沿东南—西北主线理解山地、平原与湿润度，再把水系、边界和生态保护地叠到地图上。区位关系和自然成因要分开。','产业与历史题分建厂、出车、拍片、更名、发射等动作；年度数字则分统计年、发布年、实绩与预期目标。相同年份或相似数字不是相同事件。'],
 'compare':[['吉林省 / 吉林市','省级区域 / 地级市','不能因同名就把吉林市当现省会'],['长春 / 延吉','省会 / 延边州首府','角色与行政层级分开'],['自治区 / 自治州 / 自治县','不同层级及历史语境','延边成立时名称与现称不同'],['近海 / 沿海','距离关系 / 海岸线属性','珲春近海不等于省域沿海'],['统计年 / 发布年','数据所属年 / 文件公布年','2026年公布的2025年公报仍属2025年数据'],['实绩 / 目标','已经统计 / 计划预期','目标不能当全年完成值']],
 'case':['题目给出“一份2026年4月发布的2025年统计公报”和“一份2026年政府工作报告”，要求比较GDP增速。','先读文件在讲哪一年、哪类数据。公报中的2025年增速是已经统计的实绩；报告中的2026年增速是预期目标。即使两个数字接近，也不能把目标写成已经完成。','用五格卡写年份、发布日、指标、单位、实绩/目标，再根据题干换问法重新判断。'],
 'method':'先在地图定位，再做角色对照；历史每节点写“何时—何地—什么动作”；产业写措施→机制→结果；数字写统计年、单位和实绩/目标。做错题时先定位自己错的是哪个维度。',
}

def extend_jilin(study):
 # Idempotent overlay: never duplicate the regional pack when rebuilding.
 study['modules']=[m for m in study['modules'] if m['id']!='m14']
 study['questions']=[q for q in study['questions'] if q['module']!='m14']
 study['knowledge']=[p for p in study['knowledge'] if p['module']!='m14']
 study['webSources']=[dict(id=id,name=name,url=url,published=published,checkedAt=CHECKED,kind='official-web') for id,(name,url,published) in SOURCES.items()]
 study['modules'].append(dict(id='m14',title='吉林省情',goal='掌握吉林地理区划、历史产业、生态文化与带年份的数据，练会对照、定位和因果分析。',reading='按下面九个小节自主学习；资料链接为官方网页，核对日期2026-10-05。',refs=[['jl-area',0],['jl-geo',0],['jl-stat2025',0],['jl-report2026',0]],cards=[[name,value[0]] for name,value in UNITS.items()],recall=['长春、吉林市、延边、延吉分别是什么角色？','东南—西北的地势和湿润度如何变化？','1953建厂、1954迁省会、1956出车怎样排列？','为什么公报发布于2026年，但其中实绩仍属于2025年？']))
 study['guides']['m14']=GUIDE
 for title,(explanation,method) in UNITS.items():study['unitGuides'][title]=dict(explanation=explanation,method=method,keywords=[])
 points={}
 for row in ROWS:
  point_id='jl-point-'+row['slug'];qid='jl-'+row['slug']
  p=dict(id=point_id,title=row['title'],statement=row['fact'],module='m14',source=row['source'],page=0,chapters=[],group=row['group'],questionIds=[qid],authored=True,checkedAt=CHECKED,reasoning=UNITS[row['group']][0],method=UNITS[row['group']][1])
  if row['year']:p['dataYear']=row['year']
  points[row['slug']]=p;study['knowledge'].append(p)
  study['questions'].append(dict(id=qid,concept=point_id,pointIds=[point_id],module='m14',source=row['source'],page=0,prompt=row['prompt'],options=row['options'],answer=0,explanation=row['fact'],optionExplanations=row['notes'],extension=row['extension'] or UNITS[row['group']][1],kind='regional',dataYear=row['year']))
 for row in EXTRA:
  point_ids=[points[slug]['id'] for slug in row['pointSlugs']];qid='jl-apply-'+row['slug']
  for slug in row['pointSlugs']:points[slug]['questionIds'].append(qid)
  study['questions'].append(dict(id=qid,concept=point_ids[0],pointIds=point_ids,module='m14',source=row['source'],page=0,prompt=row['prompt'],options=row['options'],answer=0,explanation=row['notes'][0],optionExplanations=row['notes'],extension=row['extension'],kind='regional-application'))
 study['timelines']=[t for t in study['timelines'] if not t['id'].startswith('jilin-')]
 study['timelines'] += [dict(id='jilin-history',title='吉林历史与产业时间线',module='m14',method='时间与动作同时记：建城、解放、成立、建厂、迁省会、更名、出车不是同一种事件。',events=[['1673年','建吉林城','吉林乌拉与沿江地名'],['1948年3月9日','吉林市解放','与长春解放时间区分'],['1948年10月19日','长春解放','两城分别定位'],['1952年9月3日','延边自治地方成立','当时称延边朝鲜族自治区'],['1953年7月15日','一汽奠基动工','建厂起点'],['1954年9月27日','吉林省会迁长春','由吉林市迁出'],['1955年','长影更名；延边改称自治州','机构更名与自治地方沿革分开'],['1956年7月13日','解放牌载货车下线','与1953年建厂区分'],['2004年','高句丽相关遗产入选','世界文化遗产节点'],['2008年','查干淖尔冬捕习俗入选','国家级非遗节点'],['2015年10月7日','吉林一号首次发射','发射场在酒泉'],['2021年10月12日','东北虎豹国家公园设立','跨吉林、黑龙江区域']]),dict(id='jilin-data',title='吉林年度数据：实绩与目标',module='m14',method='数据卡写统计年度和实绩/目标状态；文件发布在下一年不改变数据所属年度。',events=[['2025年度','GDP和粮食产量实绩','GDP14973.88亿元、可比价增长5.0%；粮食4358.03万吨、增长2.2%'],['2026年1月27日报告','2026年年度预期目标','GDP增长5%左右，规上工业增加值增长6%左右'],['2026年4月27日公布','发布2025年统计公报','发布日期与统计年不同，不写成2026年全年实绩']])]
 study['eventLines']=[e for e in study['eventLines'] if e.get('region')!='jilin']
 study['eventLines'] += [dict(title='吉林黑土地：从措施解释成效',module='m14',region='jilin',steps=[['措施','秸秆覆盖、保护性耕作'],['机制','减少侵蚀、保墒养地'],['结果','支持地力和农业持续利用'],['边界','因地制宜，技术模式不等于年度增产数字']]),dict(title='吉林省情答题的五个维度',module='m14',region='jilin',steps=[['定位','地图位置与行政层级'],['辨析','名称、角色与类别'],['排序','年份和事件动作'],['核对','指标、单位、数据年与目标/实绩']])]
 study['regionalPages']=[dict(p=i+1,c='吉林省情',s='jilin-notes',t=title+'\n'+explanation+'\n学习方法：'+method+'\n'+'\n'.join(p['title']+'：'+p['statement'] for p in points.values() if p['group']==title)+'\n核对日期：'+CHECKED) for i,(title,(explanation,method)) in enumerate(UNITS.items())]
 study['coverage'].update(points=len(study['knowledge']),withQuestions=sum(bool(p['questionIds']) for p in study['knowledge']),questions=len(study['questions']),jilinPoints=len(points),jilinQuestions=len(ROWS)+len(EXTRA))
 assert all(p['questionIds'] for p in points.values())
 assert len({q['id'] for q in study['questions']})==len(study['questions'])
